impl Document {
    pub(crate) fn compare_dlt_application(
        &self,
        other: &Document,
        a: &DltApplication,
        b: &DltApplication,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_application_description() != b.get_application_description() {
            return Err(format!("{path}: APPLICATION_DESCRIPTION mismatch"));
        }
        if a.get_application_id() != b.get_application_id() {
            return Err(format!("{path}: APPLICATION_ID mismatch"));
        }
        let list_a = a.get_context_refs();
        let list_b = b.get_context_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CONTEXT_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.CONTEXT_REFS[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_dlt_argument(
        &self,
        other: &Document,
        a: &DltArgument,
        b: &DltArgument,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_dlt_argument_entries();
        let list_b = b.get_dlt_argument_entries();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DLT_ARGUMENT_ENTRIES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.dlt_arguments.get(*x).ok_or_else(|| {
                format!("{path}.DLT_ARGUMENT_ENTRIES[{index}]: id not found in own arena")
            })?;
            let y = other.dlt_arguments.get(*y).ok_or_else(|| {
                format!("{path}.DLT_ARGUMENT_ENTRIES[{index}]: id not found in other arena")
            })?;
            self.compare_dlt_argument(
                other,
                x,
                y,
                &format!("{path}.DLT_ARGUMENT_ENTRIES[{index}]"),
            )?;
        }
        if a.get_length() != b.get_length() {
            return Err(format!("{path}: LENGTH mismatch"));
        }
        if a.get_network_representation() != b.get_network_representation() {
            return Err(format!("{path}: NETWORK_REPRESENTATION mismatch"));
        }
        if a.get_optional() != b.get_optional() {
            return Err(format!("{path}: OPTIONAL mismatch"));
        }
        if a.get_predefined_text() != b.get_predefined_text() {
            return Err(format!("{path}: PREDEFINED_TEXT mismatch"));
        }
        if a.get_variable_length() != b.get_variable_length() {
            return Err(format!("{path}: VARIABLE_LENGTH mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_dlt_context(
        &self,
        other: &Document,
        a: &DltContext,
        b: &DltContext,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        if a.get_context_description() != b.get_context_description() {
            return Err(format!("{path}: CONTEXT_DESCRIPTION mismatch"));
        }
        if a.get_context_id() != b.get_context_id() {
            return Err(format!("{path}: CONTEXT_ID mismatch"));
        }
        let list_a = a.get_dlt_message_refs();
        let list_b = b.get_dlt_message_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DLT_MESSAGE_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.DLT_MESSAGE_REFS[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_dlt_ecu(
        &self,
        other: &Document,
        a: &DltEcu,
        b: &DltEcu,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_applications();
        let list_b = b.get_applications();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: APPLICATIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.dlt_applications.get(*x).ok_or_else(|| {
                format!("{path}.APPLICATIONS[{index}]: id not found in own arena")
            })?;
            let y = other.dlt_applications.get(*y).ok_or_else(|| {
                format!("{path}.APPLICATIONS[{index}]: id not found in other arena")
            })?;
            self.compare_dlt_application(other, x, y, &format!("{path}.APPLICATIONS[{index}]"))?;
        }
        if a.get_ecu_id() != b.get_ecu_id() {
            return Err(format!("{path}: ECU_ID mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_dlt_message(
        &self,
        other: &Document,
        a: &DltMessage,
        b: &DltMessage,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_dlt_arguments();
        let list_b = b.get_dlt_arguments();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DLT_ARGUMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.dlt_arguments.get(*x).ok_or_else(|| {
                format!("{path}.DLT_ARGUMENTS[{index}]: id not found in own arena")
            })?;
            let y = other.dlt_arguments.get(*y).ok_or_else(|| {
                format!("{path}.DLT_ARGUMENTS[{index}]: id not found in other arena")
            })?;
            self.compare_dlt_argument(other, x, y, &format!("{path}.DLT_ARGUMENTS[{index}]"))?;
        }
        if a.get_message_id() != b.get_message_id() {
            return Err(format!("{path}: MESSAGE_ID mismatch"));
        }
        if a.get_message_line_number() != b.get_message_line_number() {
            return Err(format!("{path}: MESSAGE_LINE_NUMBER mismatch"));
        }
        if a.get_message_source_file() != b.get_message_source_file() {
            return Err(format!("{path}: MESSAGE_SOURCE_FILE mismatch"));
        }
        if a.get_message_type_info() != b.get_message_type_info() {
            return Err(format!("{path}: MESSAGE_TYPE_INFO mismatch"));
        }
        if a.get_privacy_level() != b.get_privacy_level() {
            return Err(format!("{path}: PRIVACY_LEVEL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_log_and_trace_message_collection_set(
        &self,
        other: &Document,
        a: &LogAndTraceMessageCollectionSet,
        b: &LogAndTraceMessageCollectionSet,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_privacy_level(
        &self,
        _other: &Document,
        a: &PrivacyLevel,
        b: &PrivacyLevel,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_compu_method_ref() != b.get_compu_method_ref() {
            return Err(format!("{path}: COMPU_METHOD_REF mismatch"));
        }
        if a.get_privacy_level() != b.get_privacy_level() {
            return Err(format!("{path}: PRIVACY_LEVEL mismatch"));
        }
        Ok(())
    }
}
